  if k <> 1 then raise exception 'Arbre Royaume de Navarre introuvable : rien n''a été fait.'; end if;
  select count(*) into k from public.dossier_entries where id = 'edd033cb-9503-535c-b756-b5d41fea2e9a' and type = 'genealogy';
  if k <> 1 then raise exception 'Arbre Maison d''Anjou-Naples introuvable : rien n''a été fait.'; end if;
